//! The protocol's closed and open vocabularies (IDL §5, plus the enums the IDL
//! declares beside the declaration that uses them).
//!
//! Every enum here is generated by [`protocol_enum!`](crate::protocol_enum), which
//! emits the Rust enum, its wire tokens, and the [`EnumSpec`] the conformance test
//! compares against the IDL. The two cannot disagree: they are one declaration.
//!
//! Closed enums decode fail-closed ([`ProtocolEnum::from_wire`] returns
//! [`UnknownMember`]); `@open` enums are decoded through [`Open`], which surfaces an
//! unrecognized token verbatim and never infers semantics from it
//! (`rule versioning.enums`).
//!
//! [`EnumSpec`]: crate::protocol::spec::EnumSpec
//! [`ProtocolEnum::from_wire`]: crate::protocol::spec::ProtocolEnum::from_wire
//! [`UnknownMember`]: crate::protocol::spec::UnknownMember
//! [`Open`]: crate::protocol::spec::Open

use crate::protocol_enum;

protocol_enum! {
    /// The five authority levels, ordered `read < propose < execute <
    /// revise-intent < promote` (RFC 0027). Agent-facing installations MUST
    /// omit `promote` and `revise_intent` by default.
    closed enum AuthorityLevel {
        /// Wire token `read`.
        read => Read,
        /// Wire token `propose`.
        propose => Propose,
        /// Wire token `execute`.
        execute => Execute,
        /// Wire token `revise-intent`.
        revise_intent = "revise-intent" => ReviseIntent,
        /// Wire token `promote`.
        promote => Promote,
    }
}

protocol_enum! {
    /// Wire encoding of a connection. One encoding per connection,
    /// negotiated at open; canonical field order is identical in both.
    closed enum Encoding {
        /// Canonical JSON (ADR-0013 canonical form), for debugging.
        canonical_json => CanonicalJson,
        /// CBOR with the same canonical field order, for performance.
        canonical_cbor => CanonicalCbor,
    }
}

